mapper.select:
select t.*, (select cb.BANK_NAME from csh_bank cb where cb.bank_id = t.bank_id) BANK_NAME_N, (select cba.BANK_ACCOUNT_NAME from csh_bank_account cba where cba.BANK_ACCOUNT_ID = t.BANK_ACCOUNT_ID)BANK_ACCOUNT_NAME, (select cba.BANK_ACCOUNT_NUM from csh_bank_account cba where cba.BANK_ACCOUNT_ID = t.BANK_ACCOUNT_ID)BANK_ACCOUNT_NUM, (SELECT MEANING FROM SYS_CODE_VALUE_B WHERE CODE_ID = (SELECT CODE_ID FROM SYS_CODE_B WHERE CODE = 'CSH.BANK_ACCOUNT_TYPE') AND VALUE = (select cba.BANK_ACCOUNT_TYPE from csh_bank_account cba where cba.BANK_ACCOUNT_ID = t.BANK_ACCOUNT_ID))BANK_ACCOUNT_TYPE_N, (SELECT MEANING FROM SYS_CODE_VALUE_B WHERE CODE_ID = (SELECT CODE_ID FROM SYS_CODE_B WHERE CODE = 'CSH.BILL_TICKET_TYPE' AND VALUE = t.TICKET_TYPE))TICKET_TYPE_N,
(select cc.contract_name from con_contract cc where cc.contract_id = t.contract_id)contract_name, (select cc.contract_number from con_contract cc where cc.contract_id = t.contract_id)contract_number, (SELECT MEANING FROM SYS_CODE_VALUE_B WHERE CODE_ID = (SELECT CODE_ID FROM SYS_CODE_B WHERE CODE = 'CON.BILL_STATUS') AND VALUE = t.bill_status)BILL_STATUS_N, (SELECT MEANING FROM SYS_CODE_VALUE_B WHERE CODE_ID = (SELECT CODE_ID FROM SYS_CODE_B WHERE CODE = 'TRANSFER_FLAG') AND VALUE = t.TRANSFERABLE_FLAG)TRANSFERABLE_FLAG_N, (case when t.wfl_status = 'APPROVED' then '审批通过' when t.wfl_status = 'APPROVED_RETURN' then '审批退回' when t.wfl_status = 'APPROVING' then '审批中' else '未提交' end)wfl_status_desc from BILL_MANAGEMENT t
and t.BILL_MANAGEMENT_BATCH_ID = #{billManagementBatchId}

select fa.file_size, fa.file_name, sa.attachment_id, (select sy.user_name from sys_user sy where sy.user_id = fa.created_by) upload_person, fa.creation_date uploaddate from bill_management bm, sys_attachment sa, fnd_atm_attachment_multi fam, fnd_atm_attachment fa
bm.bill_management_id = sa.source_key and sa.source_type = 'BILL_MANAGEMENT_ATTACHMENT' and fam.table_pk_value = sa.attachment_id and fam.table_name = 'SYS_ATTACHMENT' and fa.attachment_id = fam.attachment_id
and bm.bill_management_id=#{billManagementId}
